'use client'

import { Fragment, type FormEvent, type ReactNode } from 'react'

import { Button } from '../../components/ui/button'
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from '../../components/ui/card'
import {
  Field,
  FieldDescription,
  FieldGroup,
  FieldLabel,
} from '../../components/ui/field'
import { Input } from '../../components/ui/input'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '../../components/ui/select'
import { Separator } from '../../components/ui/separator'
import { Switch } from '../../components/ui/switch'
import { Textarea } from '../../components/ui/textarea'

export type SettingsPanelOption = { label: string; value: string }

type SettingsPanelFieldBase = {
  id: string
  label: string
  description?: string
  disabled?: boolean
}

export type SettingsPanelField =
  | (SettingsPanelFieldBase & {
      kind: 'text'
      type?: 'text' | 'email' | 'url'
      placeholder?: string
      value?: string
      defaultValue?: string
      onChange?: (value: string) => void
    })
  | (SettingsPanelFieldBase & {
      kind: 'textarea'
      placeholder?: string
      rows?: number
      value?: string
      defaultValue?: string
      onChange?: (value: string) => void
    })
  | (SettingsPanelFieldBase & {
      kind: 'switch'
      checked?: boolean
      defaultChecked?: boolean
      onCheckedChange?: (checked: boolean) => void
    })
  | (SettingsPanelFieldBase & {
      kind: 'select'
      placeholder?: string
      options: SettingsPanelOption[]
      value?: string
      defaultValue?: string
      onValueChange?: (value: string) => void
    })

export type SettingsPanelSection = {
  id: string
  title: string
  description?: string
  fields: SettingsPanelField[]
}

export type SettingsPanel01Props = {
  title: string
  description?: string
  /** The settings groups, each rendered with a heading and its own fields. */
  sections: SettingsPanelSection[]
  /** The submit button label. Omit to render no footer. */
  submitLabel?: string
  onSubmit?: (event: FormEvent<HTMLFormElement>) => void
  /** A secondary control, such as Cancel. */
  secondaryAction?: { label: string; onClick?: () => void }
  /** Extra content in the footer, e.g. a status note. */
  footer?: ReactNode
}

function SettingsField({ field }: { field: SettingsPanelField }) {
  if (field.kind === 'switch') {
    return (
      <Field className="flex-row items-center justify-between gap-4">
        <div className="flex flex-col gap-0.5">
          <FieldLabel htmlFor={field.id}>{field.label}</FieldLabel>
          {field.description ? (
            <FieldDescription>{field.description}</FieldDescription>
          ) : null}
        </div>
        <Switch
          id={field.id}
          checked={field.checked}
          defaultChecked={field.defaultChecked}
          onCheckedChange={field.onCheckedChange}
          disabled={field.disabled}
        />
      </Field>
    )
  }

  if (field.kind === 'select') {
    return (
      <Field>
        <FieldLabel htmlFor={field.id}>{field.label}</FieldLabel>
        <Select
          value={field.value}
          defaultValue={field.defaultValue}
          onValueChange={
            field.onValueChange
              ? (value) => field.onValueChange?.(value ?? '')
              : undefined
          }
          disabled={field.disabled}
          items={Object.fromEntries(field.options.map((option) => [option.value, option.label]))}
        >
          <SelectTrigger id={field.id} className="w-full">
            <SelectValue placeholder={field.placeholder} />
          </SelectTrigger>
          <SelectContent>
            {field.options.map((option) => (
              <SelectItem key={option.value} value={option.value}>
                {option.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        {field.description ? <FieldDescription>{field.description}</FieldDescription> : null}
      </Field>
    )
  }

  if (field.kind === 'textarea') {
    return (
      <Field>
        <FieldLabel htmlFor={field.id}>{field.label}</FieldLabel>
        <Textarea
          id={field.id}
          rows={field.rows}
          placeholder={field.placeholder}
          value={field.value}
          defaultValue={field.defaultValue}
          onChange={field.onChange ? (event) => field.onChange?.(event.target.value) : undefined}
          disabled={field.disabled}
        />
        {field.description ? <FieldDescription>{field.description}</FieldDescription> : null}
      </Field>
    )
  }

  return (
    <Field>
      <FieldLabel htmlFor={field.id}>{field.label}</FieldLabel>
      <Input
        id={field.id}
        type={field.type ?? 'text'}
        placeholder={field.placeholder}
        value={field.value}
        defaultValue={field.defaultValue}
        onChange={field.onChange ? (event) => field.onChange?.(event.target.value) : undefined}
        disabled={field.disabled}
      />
      {field.description ? <FieldDescription>{field.description}</FieldDescription> : null}
    </Field>
  )
}

/**
 * A settings form grouped into sections.
 *
 * A field is a small object describing one control: a text input, a textarea,
 * a select or a switch, with its label, description and value handlers. The
 * block renders the card, the groups and the footer; it owns no values and no
 * copy, so a consumer wires it to whatever form state or mutation they use.
 */
export function SettingsPanel01({
  title,
  description,
  sections,
  submitLabel,
  onSubmit,
  secondaryAction,
  footer,
}: SettingsPanel01Props) {
  const hasFooter = Boolean(submitLabel || secondaryAction || footer)

  return (
    <form onSubmit={onSubmit} className="w-full">
      <Card>
        <CardHeader>
          <CardTitle>{title}</CardTitle>
          {description ? <CardDescription>{description}</CardDescription> : null}
        </CardHeader>

        <CardContent className="flex flex-col">
          {sections.map((section, index) => (
            <Fragment key={section.id}>
              {index > 0 ? <Separator className="my-6" /> : null}
              <section className="flex flex-col gap-4" aria-labelledby={`${section.id}-heading`}>
                <div className="flex flex-col gap-1">
                  <h3
                    id={`${section.id}-heading`}
                    className="text-lg font-semibold tracking-tight"
                  >
                    {section.title}
                  </h3>
                  {section.description ? (
                    <p className="text-muted-foreground text-sm">{section.description}</p>
                  ) : null}
                </div>
                <FieldGroup>
                  {section.fields.map((field) => (
                    <SettingsField key={field.id} field={field} />
                  ))}
                </FieldGroup>
              </section>
            </Fragment>
          ))}
        </CardContent>

        {hasFooter ? (
          <CardFooter className="justify-end gap-2">
            {footer}
            {secondaryAction ? (
              <Button type="button" variant="outline" onClick={secondaryAction.onClick}>
                {secondaryAction.label}
              </Button>
            ) : null}
            {submitLabel ? <Button type="submit">{submitLabel}</Button> : null}
          </CardFooter>
        ) : null}
      </Card>
    </form>
  )
}

export default SettingsPanel01

import type { ReactNode } from 'react'
import { cn } from '../../lib/utils'

/**
 * Container primitive. Every block composes its own section from this so vertical
 * rhythm stays consistent across the catalog instead of being re-invented per block.
 */
export function Section({
  className,
  children,
  ...props
}: React.ComponentProps<'section'>) {
  return (
    <section
      className={cn('py-16 sm:py-24', className)}
      {...props}
    >
      <div className="mx-auto w-full max-w-6xl px-6 lg:px-8">
        {children}
      </div>
    </section>
  )
}

/**
 * The six heading levels a block can be composed at.
 *
 * Every block takes a `headingLevel` prop typed with this and forwards it to the
 * one heading it renders, so the surrounding document decides where the block
 * sits in the outline rather than the block deciding for itself. `h2` is the
 * default because a block is composed, not a page.
 *
 * A block rendered where the document *already* owns a heading for the same
 * content passes one level deeper. A catalog card already names the block in its
 * own `h2`, so the copy of the block embedded inside that card passes `h3`: the
 * embedded heading then reads as a child of the card that introduces it instead
 * of as a second, competing sibling. This is a fact about where the block was
 * placed, not about the block, which is why it is a prop and not a default.
 */
export type HeadingLevel = 'h1' | 'h2' | 'h3' | 'h4' | 'h5' | 'h6'

export function SectionHeading({
  eyebrow,
  title,
  as: Heading = 'h2',
  description,
  align = 'center',
  className,
}: {
  eyebrow?: ReactNode
  title: ReactNode
  description?: ReactNode
  align?: 'center' | 'left'
  /**
   * Heading level. Defaults to `h2` because blocks compose under a page heading.
   * A page that renders a block as its primary heading passes `as="h1"`; a
   * document with no `h1` gives screen-reader and search engines no top-level
   * entry point.
   */
  as?: HeadingLevel
  className?: string
}) {
  return (
    <div
      className={cn(
        'flex flex-col gap-4',
        align === 'center' ? 'items-center text-center' : 'items-start text-left',
        className,
      )}
    >
      {eyebrow ? (
        <span className="text-muted-foreground text-sm font-medium tracking-wide uppercase">
          {eyebrow}
        </span>
      ) : null}
      <Heading className="text-3xl font-semibold tracking-tight text-balance sm:text-4xl">
        {title}
      </Heading>
      {description ? (
        <p className="text-muted-foreground max-w-2xl text-lg text-pretty">
          {description}
        </p>
      ) : null}
    </div>
  )
}

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
